import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
// C = triu(A * B) for row-major N x N float32 matrices.
// Each block computes a 32x32 tile of C; each thread computes a 2x2 sub-tile.
// Blocks whose tile lies entirely below the diagonal just write zeros.
.version 7.8
.target sm_89
.address_size 64

.visible .entry triu_matmul_kernel(
    .param .u64 triu_matmul_kernel_param_0,
    .param .u64 triu_matmul_kernel_param_1,
    .param .u64 triu_matmul_kernel_param_2,
    .param .u32 triu_matmul_kernel_param_3
)
{
    .reg .pred %p<8>;
    .reg .b32  %r<40>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<16>;

    .shared .align 16 .b8 tile_a[4224];   // 32 x 33 floats (padded)
    .shared .align 16 .b8 tile_b[4224];   // 32 x 33 floats (padded)

    ld.param.u64 %rd1, [triu_matmul_kernel_param_0];  // A
    ld.param.u64 %rd2, [triu_matmul_kernel_param_1];  // B
    ld.param.u64 %rd3, [triu_matmul_kernel_param_2];  // C
    ld.param.u32 %r7,  [triu_matmul_kernel_param_3];  // n

    mov.u32 %r1, %tid.x;     // tx in [0,16)
    mov.u32 %r2, %tid.y;     // ty in [0,16)
    mov.u32 %r3, %ctaid.x;   // bx
    mov.u32 %r4, %ctaid.y;   // by

    shl.b32 %r5, %r3, 5;     // col0 = bx * 32
    shl.b32 %r6, %r4, 5;     // row0 = by * 32

    shl.b32 %r9, %r2, 1;     // ty*2
    shl.b32 %r10, %r1, 1;    // tx*2
    add.s32 %r11, %r6, %r9;  // row_g0 = row0 + ty*2
    add.s32 %r12, %r5, %r10; // col_g0 = col0 + tx*2

    // tile entirely below the diagonal? (col0+31 < row0)
    add.s32 %r8, %r5, 31;
    setp.lt.s32 %p1, %r8, %r6;
    @%p1 bra WRITE_ZERO;

    // accumulators
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;

    // shared base addresses
    mov.u64 %rd10, tile_a;
    mov.u64 %rd11, tile_b;

    // per-thread persistent shared bases
    mul.lo.s32 %r20, %r9, 132;          // (ty*2)*33*4 bytes
    cvt.u64.u32 %rd12, %r20;
    add.s64 %rd14, %rd10, %rd12;        // &As[ty*2][0]
    shl.b32 %r21, %r10, 2;              // (tx*2)*4 bytes
    cvt.u64.u32 %rd13, %r21;
    add.s64 %rd15, %rd11, %rd13;        // &Bs[0][tx*2]

    // linear thread id for cooperative loads
    shl.b32 %r14, %r2, 4;
    add.s32 %r14, %r14, %r1;            // tid in [0,256)

    mov.u32 %r13, 0;                    // k0 = 0

K_TILE_LOOP:
    // -------- cooperative 32x32 tile load --------
    mov.u32 %r15, %r14;                 // idx = tid
COOP_LOAD_LOOP:
    shr.u32 %r16, %r15, 5;              // rr = idx / 32
    and.b32 %r17, %r15, 31;             // cc = idx % 32

    mul.lo.s32 %r20, %r16, 33;
    add.s32 %r20, %r20, %r17;           // rr*33 + cc
    shl.b32 %r21, %r20, 2;              // byte offset
    cvt.u64.u32 %rd12, %r21;

    // A[row0+rr][k0+cc] (zero-fill out of bounds)
    add.s32 %r18, %r6, %r16;
    add.s32 %r19, %r13, %r17;
    setp.lt.s32 %p2, %r18, %r7;
    setp.lt.s32 %p3, %r19, %r7;
    and.pred %p4, %p2, %p3;
    mov.f32 %f9, 0f00000000;
    @!%p4 bra A_LOAD_DONE;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd1, %rd7;
    ld.global.f32 %f9, [%rd8];
A_LOAD_DONE:
    add.s64 %rd9, %rd10, %rd12;
    st.shared.f32 [%rd9], %f9;

    // B[k0+rr][col0+cc] (zero-fill out of bounds)
    add.s32 %r18, %r13, %r16;
    add.s32 %r19, %r5, %r17;
    setp.lt.s32 %p2, %r18, %r7;
    setp.lt.s32 %p3, %r19, %r7;
    and.pred %p4, %p2, %p3;
    mov.f32 %f9, 0f00000000;
    @!%p4 bra B_LOAD_DONE;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f9, [%rd8];
B_LOAD_DONE:
    add.s64 %rd9, %rd11, %rd12;
    st.shared.f32 [%rd9], %f9;

    add.s32 %r15, %r15, 256;
    setp.lt.s32 %p5, %r15, 1024;
    @%p5 bra COOP_LOAD_LOOP;

    bar.sync 0;

    // -------- 2x2 register-blocked FMA over 32-wide k tile --------
    mov.u32 %r26, 0;                    // kk = 0
INNER_K_LOOP:
    shl.b32 %r27, %r26, 2;              // kk*4
    cvt.u64.u32 %rd16, %r27;
    add.s64 %rd17, %rd14, %rd16;
    ld.shared.f32 %f5, [%rd17];         // a0 = As[ty*2][kk]
    ld.shared.f32 %f6, [%rd17+132];     // a1 = As[ty*2+1][kk]

    mul.lo.s32 %r29, %r26, 132;         // kk*33*4
    cvt.u64.u32 %rd18, %r29;
    add.s64 %rd19, %rd15, %rd18;
    ld.shared.f32 %f7, [%rd19];         // b0 = Bs[kk][tx*2]
    ld.shared.f32 %f8, [%rd19+4];       // b1 = Bs[kk][tx*2+1]

    fma.rn.f32 %f1, %f5, %f7, %f1;
    fma.rn.f32 %f2, %f5, %f8, %f2;
    fma.rn.f32 %f3, %f6, %f7, %f3;
    fma.rn.f32 %f4, %f6, %f8, %f4;

    add.s32 %r26, %r26, 1;
    setp.lt.s32 %p6, %r26, 32;
    @%p6 bra INNER_K_LOOP;

    bar.sync 0;

    add.s32 %r13, %r13, 32;
    setp.lt.s32 %p7, %r13, %r7;
    @%p7 bra K_TILE_LOOP;

    // -------- store 2x2 results with upper-triangular mask --------
    mov.f32 %f0, 0f00000000;

    // element (row_g0, col_g0)
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra STORE_1;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra STORE_1;
    setp.ge.s32 %p4, %r12, %r11;
    selp.f32 %f10, %f1, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f10;
STORE_1:
    // element (row_g0, col_g0+1)
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra STORE_2;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra STORE_2;
    setp.ge.s32 %p4, %r19, %r11;
    selp.f32 %f10, %f2, %f0, %p4;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f10;
STORE_2:
    // element (row_g0+1, col_g0)
    add.s32 %r18, %r11, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra STORE_3;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra STORE_3;
    setp.ge.s32 %p4, %r12, %r18;
    selp.f32 %f10, %f3, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f10;
STORE_3:
    // element (row_g0+1, col_g0+1)
    add.s32 %r18, %r11, 1;
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra STORE_DONE;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra STORE_DONE;
    setp.ge.s32 %p4, %r19, %r18;
    selp.f32 %f10, %f4, %f0, %p4;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f10;
STORE_DONE:
    bra EXIT;

WRITE_ZERO:
    mov.f32 %f0, 0f00000000;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra Z_1;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra Z_1;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f0;
Z_1:
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r11, %r7;
    @!%p2 bra Z_2;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra Z_2;
    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f0;
Z_2:
    add.s32 %r18, %r11, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra Z_3;
    setp.lt.s32 %p3, %r12, %r7;
    @!%p3 bra Z_3;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r12;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f0;
Z_3:
    add.s32 %r18, %r11, 1;
    add.s32 %r19, %r12, 1;
    setp.lt.s32 %p2, %r18, %r7;
    @!%p2 bra EXIT;
    setp.lt.s32 %p3, %r19, %r7;
    @!%p3 bra EXIT;
    mul.wide.s32 %rd4, %r18, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
    st.global.f32 [%rd8], %f0;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        n = A.shape[0]
        C = torch.empty((A.shape[0], A.shape[1]), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        tiles = (n + 31) // 32
        module.launch(
            "triu_matmul_kernel",
            grid=(tiles, tiles, 1),
            block=(16, 16, 1),
            arguments=[A, B, C, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

