    mul.wide.s32 %rd4, %r11, %r7;
    cvt.u64.u32 %rd5, %r19;
    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd3, %rd7;
